CSS = ":root{--bg:#020202;--card:#080808;--text:#ccc;--orange:#f97316;--blue:#2563eb;--gray:#181818;--success:#059669;--error:#dc2626;--border:#1a1a1a}body{font-family:monospace;background:var(--bg);color:var(--text);margin:0;padding:30px;line-height:1.4;max-width:1600px;margin-left:auto;margin-right:auto}.header{border-left:3px solid var(--orange);padding-left:15px;margin-bottom:30px}.header h1{margin:0;color:#fff;font-size:26px;font-weight:900}.header p{color:#666;margin:5px 0 0 0;font-size:12px;text-transform:uppercase}.status-badge{font-size:11px;padding:4px 8px;font-weight:700;border:1px solid var(--border);background:var(--gray);color:var(--orange);vertical-align:middle;margin-left:10px;text-transform:uppercase}.dashboard{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:15px;margin-bottom:20px}.stat-card{background:var(--card);padding:20px;border:1px solid var(--border);border-radius:0}.stat-card small{color:#555;text-transform:uppercase;font-size:11px;display:block;margin-bottom:5px}.stat-card div{font-size:22px;font-weight:700;color:#eee}.controls{display:flex;flex-direction:column;gap:12px;margin-bottom:20px}.search-row{display:flex;gap:8px}.search-box{flex:1;padding:12px;background:var(--card);border:1px solid var(--border);border-radius:0;color:#fff;font-size:13px;outline:none}.reset-btn{padding:0 20px;background:var(--gray);border:1px solid var(--border);border-radius:0;color:#fff;font-size:11px;font-weight:700;cursor:pointer}.toggle-row{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.toggle-label{font-size:11px;color:#555;text-transform:uppercase;margin-right:5px}.toggle-btn{padding:6px 12px;background:#111;border:1px solid var(--border);border-radius:0;color:#888;font-size:11px;cursor:pointer;transition:all 0.2s}.toggle-btn.active{background:#222;color:#fff;border-color:#444}.table-container{background:var(--card);border:1px solid var(--border);border-radius:0;overflow-x:auto;contain:layout}table{width:100%;border-collapse:collapse;text-align:left;min-width:1100px;table-layout:auto}th{background:#0a0a0a;color:#fff;padding:14px 12px;font-size:12px;text-transform:uppercase;border-bottom:1px solid var(--border);cursor:pointer}td{padding:12px;border-bottom:1px solid #0f0f0f;font-size:13px;word-break:break-all}.path-cell{color:#888}.status-tag{padding:4px 8px;font-size:10px;font-weight:700;text-transform:uppercase;border:1px solid transparent;border-radius:0;white-space:nowrap;display:inline-block}.hidden-col{display:none !important}"